</confidence>
Do not provide any other text or markdown fences.

Here is the problem description:
<problem_description>
They've screwed something up yet again... In one nuclear reactor of a research station an uncontrolled reaction is in progress and explosion which will destroy the whole station will happen soon.The station is represented by a square n × n divided into 1 × 1 blocks. Each block is either a reactor or a laboratory. There can be several reactors and exactly one of them will explode soon. The reactors can be considered impassable blocks, but one can move through laboratories. Between any two laboratories, which are in adjacent blocks, there is a corridor. Blocks are considered adjacent if they have a common edge.In each laboratory there is some number of scientists and some number of rescue capsules. Once the scientist climbs into a capsule, he is considered to be saved. Each capsule has room for not more than one scientist.The reactor, which is about to explode, is damaged and a toxic coolant trickles from it into the neighboring blocks. The block, which contains the reactor, is considered infected. Every minute the coolant spreads over the laboratories through corridors. If at some moment one of the blocks is infected, then the next minute all the neighboring laboratories also become infected. Once a lab is infected, all the scientists there that are not in rescue capsules die. The coolant does not spread through reactor blocks.There are exactly t minutes to the explosion. Any scientist in a minute can move down the corridor to the next lab, if it is not infected. On any corridor an unlimited number of scientists can simultaneously move in both directions. It is believed that the scientists inside a lab moves without consuming time. Moreover, any scientist could get into the rescue capsule instantly. It is also believed that any scientist at any given moment always has the time to perform their actions (move from the given laboratory into the next one, or climb into the rescue capsule) before the laboratory will be infected.Find the maximum number of scientists who will be able to escape.
</problem_description>

Here is the GNU C++ code you have to repair:
<original_code>
#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <climits>
#include <algorithm>
#include <cctype>
using namespace std;

struct FlowEdge {
    int src, dst, cap, rev;
    FlowEdge(int s, int d, int c, int r) : src(s), dst(d), cap(c), rev(r) {}
};

vector<FlowEdge> flowEdges;
vector<vector<int>> adjacency;

int dinicBFS(int source, int sink, vector<int>& level) {
    fill(level.begin(), level.end(), -1);
    queue<int> q;
    q.push(source);
    level[source] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int idx : adjacency[u]) {
            int v = flowEdges[idx].dst;
            if (flowEdges[idx].cap > 0 && level[v] == -1) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[sink] != -1;
}

int dinicDFS(int u, int sink, int flow, vector<int>& ptr, vector<int>& level) {
    if (u == sink) return flow;
    for (int& i = ptr[u]; i < adjacency[u].size(); ++i) {
        int e = adjacency[u][i];
        int v = flowEdges[e].dst;
        if (flowEdges[e].cap > 0 && level[v] == level[u] + 1) {
            int pushed = dinicDFS(v, sink, min(flow, flowEdges[e].cap), ptr, level);
            if (pushed > 0) {
                flowEdges[e].cap -= pushed;
                flowEdges[e ^ 1].cap += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int maxFlow(int source, int sink) {
    int total = 0;
    vector<int> level(flowEdges.size() / 2 + 10);
    while (dinicBFS(source, sink, level)) {
        vector<int> ptr(flowEdges.size() / 2 + 10, 0);
        while (int pushed = dinicDFS(source, sink, INT_MAX, ptr, level)) {
            total += pushed;
        }
    }
    return total;
}

void addFlowEdge(int u, int v, int cap, bool directed = true) {
    flowEdges.emplace_back(u, v, cap, flowEdges.size() + 1);
    adjacency[u].push_back(flowEdges.size() - 1);
    flowEdges.emplace_back(v, u, directed ? 0 : cap, flowEdges.size() - 2);
    adjacency[v].push_back(flowEdges.size() - 1);
}

const int MAX = 11;
int N, T;
char grid[MAX][MAX][MAX];
const int dx[4] = {1, -1, 0, 0};
const int dy[4] = {0, 0, 1, -1};

void spreadZ() {
    for (int t = 0; t < T; ++t) {
        for (int x = 0; x < N; ++x)
            for (int y = 0; y < N; ++y)
                strcpy(grid[x][y] + t + 1, grid[x][y] + t);
        for (int x = 0; x < N; ++x) {
            for (int y = 0; y < N; ++y) {
                if (grid[x][y][t] == 'Z') {
                    for (int k = 0; k < 4; ++k) {
                        int nx = x + dx[k], ny = y + dy[k];
                        if (nx >= 0 && ny >= 0 && nx < N && ny < N && grid[nx][ny][t] != 'Y')
                            grid[nx][ny][t + 1] = 'Z';
                    }
                }
            }
        }
    }
}

struct BFSNode {
    int x, y, depth;
    BFSNode(int a, int b, int d) : x(a), y(b), depth(d) {}
};

bool vis[MAX][MAX][MAX];

int encode(int x, int y, int size) { return x * size + y; }
int inV(int u) { return u + N * N; }
int outV(int u) { return u; }

void bfsSearch(int sx, int sy) {
    memset(vis, 0, sizeof(vis));
    queue<BFSNode> q;
    q.emplace(sx, sy, 0);
    vis[sx][sy][0] = true;
    while (!q.empty()) {
        BFSNode cur = q.front(); q.pop();
        if (cur.depth > T) continue;
        if (isdigit(grid[cur.x][cur.y][0])) {
            addFlowEdge(encode(sx, sy, N), inV(encode(cur.x, cur.y, N)), grid[sx][sy][0] - '0', false);
        }
        if (grid[cur.x][cur.y][cur.depth] == 'Z') continue;
        for (int k = 0; k < 4; ++k) {
            int nx = cur.x + dx[k], ny = cur.y + dy[k];
            if (nx >= 0 && ny >= 0 && nx < N && ny < N && grid[nx][ny][cur.depth] != 'Y' && grid[nx][ny][cur.depth] != 'Z' && !vis[nx][ny][cur.depth]) {
                vis[nx][ny][cur.depth] = true;
                q.emplace(nx, ny, cur.depth + 1);
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> T;
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            cin >> grid[i][j][0];

    spreadZ();

    int src = 3 * N * N;
    int dst = src + 1;
    flowEdges.clear();
    adjacency.assign(5 * N * N, vector<int>());

    char room[MAX][MAX];
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            cin >> room[i][j];

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (isdigit(room[i][j]) && room[i][j] != '0') {
                addFlowEdge(inV(encode(i, j, N)), inV(inV(encode(i, j, N))), room[i][j] - '0', false);
                addFlowEdge(inV(inV(encode(i, j, N))), dst, 1 << 30, false);
            }
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (isdigit(grid[i][j][0]) && grid[i][j][0] != '0') {
                bfsSearch(i, j);
                addFlowEdge(src, encode(i, j, N), grid[i][j][0] - '0', false);
            }
        }
    }

    cout << maxFlow(src, dst) << '\n';
    return 0;
}
